    h, w = len(grid), len(grid[0])
    motifs=[]
    for r in range(h-2):
        for c in range(w-2):
            if all(grid[r+i][c+j] == (2 if (i,j)==(1,1) else 3) for i in range(3) for j in range(3)):
                motifs.append((r,c))
    for r,c in motifs:
        # Stamp a one-colored plus over the connected perpendicular blue grid lines
        # intersecting the motif center; preserve blue cells where the lines cross.
        for rr in range(h):
            if grid[rr][c+1] == 2 and rr not in range(r,r+3):
                # axis line extends along its whole column; paint non-blue cells
                if grid[rr][c+1] == 2: continue
            # continue the center column as a ray through blank compartments
        # General observed rule: the 1s are placed in all blank cells of the two
        # rows/columns adjacent to each motif, extending to the next separator.
        # Derive through neighboring 2-valued separator lines.
        # Demo shows fill across a full compartment row and column, stopping at 2s.
        # fill vertical center-ray rows between horizontal separators
        for step in (-1,1):
            rr=r+1+step
            while 0 <= rr < h and grid[rr][c+1] != 2:
                # Keep blank-only cells on axis
                if out[rr][c+1] == 0: out[rr][c+1]=1
                rr += step
        for step in (-1,1):
            cc=c+1+step
            while 0 <= cc < w and grid[r+1][cc] != 2:
                if out[r+1][cc] == 0: out[r+1][cc]=1
                cc += step
        # Fill crossbar rows/columns corresponding to one cell beyond motif's edges,
        # extending through blanks until barriers, as demonstrated around each motif.
        for rr in (r, r+2):
            for step in (-1,1):
                cc=c+1+step
                while 0<=cc<w and grid[rr][cc] != 2:
                    if out[rr][cc]==0: out[rr][cc]=1
                    cc+=step
        for cc in (c,c+2):
            for step in (-1,1):
                rr=r+1+step
                while 0<=rr<h and grid[rr][cc] != 2:
                    if out[rr][cc]==0: out[rr][cc]=1
                    rr+=step
    return out
