def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    centers=[]
    for r in range(h-2):
        for c in range(w-2):
            if all(grid[r+i][c+j] == (2 if (i,j)==(1,1) else 3) for i in range(3) for j in range(3)):
                centers.append((r+1,c+1))
    for y,x in centers:
        # Propagate along an axis only where the center's initial ray is not blocked by a separator.
        for dy,dx in ((0,1),(0,-1),(1,0),(-1,0)):
            ny,nx=y+dy,x+dx
            if not (0<=ny<h and 0<=nx<w) or grid[ny][nx]==2:
                continue
            r,c=ny,nx
            while 0<=r<h and 0<=c<w:
                if grid[r][c]==0: out[r][c]=1
                if grid[r][c]==2:
                    # Crossing separator gets a one-cell side splash.
                    for rr in range(max(0,r-1),min(h,r+2)):
                        for cc in range(max(0,c-1),min(w,c+2)):
                            if grid[rr][cc]==0: out[rr][cc]=1
                r+=dy; c+=dx
    return out
