def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    centers=[]
    for r in range(h-2):
        for c in range(w-2):
            if all(grid[r+i][c+j] == (2 if (i,j)==(1,1) else 3) for i in range(3) for j in range(3)):
                centers.append((r+1,c+1))
    for y,x in centers:
        # Extend perpendicular to the blue separator passing through the motif center.
        vertical_separator = sum(grid[rr][x] == 2 for rr in range(h)) >= h-3
        horizontal_separator = sum(grid[y][cc] == 2 for cc in range(w)) >= w-3
        if vertical_separator:
            for c in range(w):
                if grid[y][c] == 0: out[y][c] = 1
            for c in range(w):
                if grid[y][c] == 2:
                    for rr in (y-1,y+1):
                        for cc in (c-1,c+1):
                            if 0<=rr<h and 0<=cc<w and grid[rr][cc] == 0: out[rr][cc] = 1
        elif horizontal_separator:
            for r in range(h):
                if grid[r][x] == 0: out[r][x] = 1
            for r in range(h):
                if grid[r][x] == 2:
                    for rr in (r-1,r+1):
                        for cc in (x-1,x+1):
                            if 0<=rr<h and 0<=cc<w and grid[rr][cc] == 0: out[rr][cc] = 1
    return out
