                   for i in range(3) for j in range(3)):
                motifs.append((r + 1, c + 1))
    for y, x in motifs:
        # Each motif lies on a vertical divider, so project its center row.
        for c in range(w):
            if grid[y][c] == 0:
                out[y][c] = 1
        # At each other vertical-divider crossing, form the 3x3 junction.
        # Keep the divider itself (and the center crossing) blue; recolor its flanks.
        for c in range(w):
            if c != x and grid[y][c] == 2:
                for yy in range(max(0, y - 1), min(h, y + 2)):
                    for xx in range(max(0, c - 1), min(w, c + 2)):
                        if xx != c and grid[yy][xx] in (0, 2):
                            out[yy][xx] = 1
                for xx in (c - 1, c + 1):
                    if 0 <= xx < w and grid[y][xx] in (0, 2):
                        out[y][xx] = 1
    return out
