    for y, x in centers:
        # Project away from the motif along the axis perpendicular to its 2-divider.
        if sum(grid[rr][x] == 2 for rr in range(h)) > h // 2:
            # Vertical divider => horizontal ray, with a 3x3 flare at crossings.
            for c in range(w):
                if grid[y][c] == 0: out[y][c] = 1
