                            if grid[rr][cc] == 0: out[rr][cc] = 1
        elif sum(grid[y][c] == 2 for c in range(w)) > w // 2:
            # Horizontal divider => vertical ray; transpose the crossing flare.
            for r in range(h):
                if grid[r][x] == 0: out[r][x] = 1
            for r in range(h):
                if r != y and grid[r][x] == 2:
