                   for i in range(3) for j in range(3)):
                centers.append((r + 1, c + 1))
    for y, x in centers:
        # The motif center lies on a vertical divider, so extend its ray horizontally.
        if sum(grid[rr][x] == 2 for rr in range(h)) > h // 2:
            for c in range(w):
                if grid[y][c] == 0:
                    out[y][c] = 1
            # Each crossed divider gets a 3x3 flare; preserve its central 2
